import{_ as t,o as a,c as r,a6 as s}from"./chunks/framework.BHBQfcoO.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/index.md","filePath":"configuration/index.md"}'),o={name:"configuration/index.md"};function i(n,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>LCARdS configuration is managed through the <strong>LCARdS Config Panel</strong>, a dedicated sidebar entry in Home Assistant that serves as the central control hub for your installation. It provides access to helper management, theme browsing, alert mode customisation, sound configuration, content pack exploration, and device/user management.</p><p>The panel is registered automatically when the LCARdS integration is installed.</p><hr><h2 id="accessing-the-panel" tabindex="-1">Accessing the Panel <a class="header-anchor" href="#accessing-the-panel" aria-label="Permalink to &quot;Accessing the Panel&quot;">​</a></h2><p>Look for the <strong>LCARdS Config</strong> entry in the Home Assistant sidebar after installation. If it is not visible:</p><ol><li>Go to <strong>Settings → Integrations → LCARdS → Configure</strong></li><li>Enable <strong>Show sidebar panel</strong></li><li>The panel appears immediately: no restart needed</li></ol><p>You can also customise the sidebar title and icon from the same screen.</p><hr><h2 id="panel-tabs" tabindex="-1">Panel Tabs <a class="header-anchor" href="#panel-tabs" aria-label="Permalink to &quot;Panel Tabs&quot;">​</a></h2><h3 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;Welcome&quot;">​</a></h3><p>The first tab when opening the Config Panel:</p><ul><li><strong>Get Started checklist</strong>: step-by-step onboarding: create helpers, configure alert mode, set up sounds</li><li><strong>Panel Guide</strong>: clickable cards for each tab with a short description; clicking navigates directly to that tab</li><li><strong>Resource links</strong>: documentation, GitHub, and community links</li></ul><hr><h3 id="helpers" tabindex="-1">Helpers <a class="header-anchor" href="#helpers" aria-label="Permalink to &quot;Helpers&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">First launch</p><p>Open the <strong>Helpers</strong> tab and click <strong>Create All Helpers</strong> before using anything else. This creates any missing HA input helper LCARdS uses for alert mode, sounds, and sizing in one step. HA-LCARS theme helpers can also be created here.</p></div><p>Shows all LCARdS HA input helpers, their current values, and creation status:</p><ul><li>Create all required helpers in one click (<strong>Create All Helpers</strong>)</li><li>Inspect or manually set individual helper values</li><li>Identify missing helpers that may affect card behaviour</li></ul><p>Helpers are standard Home Assistant <code>input_*</code> entities and persist across restarts.</p><p>→ <a href="./persistent-helpers.html">Persistent Helpers reference</a></p><hr><h3 id="theme-studio" tabindex="-1">Theme Studio <a class="header-anchor" href="#theme-studio" aria-label="Permalink to &quot;Theme Studio&quot;">​</a></h3><p>The theme tools, one per tab:</p><ul><li><strong>LCARdS Alert Mode Lab</strong>: customise the colour palette applied per alert level (<code>red_alert</code>, <code>yellow_alert</code>, <code>blue_alert</code>, <code>gray_alert</code>, <code>black_alert</code>). Adjust hue, saturation, lightness, and anchor parameters, preview changes live across your dashboard, then save to helpers.</li><li><strong>HA-LCARS Theme Lab</strong>: build an HA-LCARS theme from the active palette.</li><li><strong>LCARdS Theme Tokens</strong>, <strong>LCARS CSS Variables</strong>, <strong>All CSS Variables</strong>: browse the active theme&#39;s tokens and the page&#39;s CSS variables. Find the exact <code>theme:colors.ui.primary</code> path to use in card config, or which CSS variable controls a colour.</li><li><strong>Token Overrides</strong>: change a token&#39;s value globally, per user or per device.</li></ul><p>A card editor&#39;s <strong>Main Engineering &gt; Theme</strong> tab lists the tokens that card uses and links here. The link <code>/lcards-config?tab=theme</code> opens this tab directly (other tabs: <code>helpers</code>, <code>connectivity</code>, <code>sounds</code>, <code>users</code>, <code>packs</code>, <code>storage</code>).</p><p>→ <a href="./alert-mode-lab.html">Alert Mode Lab</a>  ·  <a href="./../core/alert-mode.html">Alert Mode</a>  ·  <a href="./../core/themes/">Themes</a></p><hr><h3 id="connectivity" tabindex="-1">Connectivity <a class="header-anchor" href="#connectivity" aria-label="Permalink to &quot;Connectivity&quot;">​</a></h3><p>Configure a full-screen overlay displayed when connection to Home Assistant is lost, ideal for kiosk installs where you always want to know when the dashboard is offline.</p><ul><li><strong>Enable / disable</strong> the overlay globally, per user, or per device</li><li><strong>Simple text</strong>: configure stylized messages</li><li><strong>Custom card</strong>: replace the simple text message with any HA card(s)</li><li><strong>Connection Restored</strong>: optional auto-dismissing confirmation shown on reconnect</li><li><strong>Effect layers</strong>: independently configure the canvas animation, colour overlay, and backdrop filter applied behind the message</li></ul><p>→ <a href="./connectivity.html">Connectivity</a></p><hr><h3 id="sounds" tabindex="-1">Sounds <a class="header-anchor" href="#sounds" aria-label="Permalink to &quot;Sounds&quot;">​</a></h3><p>Configure LCARS-style audio feedback for card interactions and alert events:</p><ul><li>Enable or disable sound categories (card interactions, UI navigation, alert sounds)</li><li>Select the active sound scheme</li><li>Set per-event overrides: change or mute individual sound events</li><li>Control master volume</li><li><strong>Per-user / per-device overrides</strong>: set different sound preferences for your own browser session without changing global defaults</li></ul><p>→ <a href="./sounds.html">Sounds</a></p><hr><h3 id="users-devices" tabindex="-1">Users &amp; Devices <a class="header-anchor" href="#users-devices" aria-label="Permalink to &quot;Users &amp; Devices&quot;">​</a></h3><p>Manage devices and users that have stored per-device or per-user setting overrides (introduced in LCARdS v2026.3.0)</p><ul><li><strong>Current Session</strong> (all users): view your device identity, set a display name for this browser</li><li><strong>Users</strong> (admin only): list users with stored overrides; clear overrides for a user</li><li><strong>Devices</strong> (admin only): list registered devices with last-seen times; rename or delete device records</li></ul><p>→ <a href="./users-devices.html">Users &amp; Devices</a></p><hr><h3 id="pack-explorer" tabindex="-1">Pack Explorer <a class="header-anchor" href="#pack-explorer" aria-label="Permalink to &quot;Pack Explorer&quot;">​</a></h3><p>Browse all installed LCARdS content packs. For each pack you can inspect:</p><ul><li><strong>Style presets</strong>: button and slider preset definitions</li><li><strong>Animations</strong>: available animation presets and their parameters</li><li><strong>Themes</strong>: theme tokens contributed by the pack</li><li><strong>Sound schemes</strong>: audio asset sets registered by the pack</li></ul><p>Built-in packs (core, buttons, sliders, effects, themes) are always shown. User-installed packs appear here once loaded.</p><hr><h3 id="storage-advanced" tabindex="-1">Storage [advanced] <a class="header-anchor" href="#storage-advanced" aria-label="Permalink to &quot;Storage [advanced]&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title"><strong>Advanced: use with caution.</strong></p><p>This tab exposes the raw key/value store on the backend integration. LCARdS uses this for persistent configuration settings that are not controlled with helpers.</p></div><ul><li><strong>Live key list</strong>: all keys currently stored</li><li><strong>Expandable JSON viewer</strong>: inspect the value of any key</li><li><strong>Inline JSON editor</strong>: edit a value directly</li><li><strong>Per-key delete</strong>: remove a single key with confirmation</li><li><strong>Reset All</strong>: wipe the entire LCARdS store (requires explicit confirmation)</li></ul><p>Typical use cases: debugging unexpected behaviour, recovering from a corrupt config value, or inspecting stored scoped settings.</p><hr><hr><h2 id="ha-lcars-theme-profiles" tabindex="-1">HA-LCARS Theme Profiles <a class="header-anchor" href="#ha-lcars-theme-profiles" aria-label="Permalink to &quot;HA-LCARS Theme Profiles&quot;">​</a></h2><p>LCARdS ships custom theme profiles designed to extend <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS</a>. They map the LCARdS colour palette to both the HA-LCARS chrome variables and the core HA colour token scale, so stock HA components, LCARdS cards, and the HA-LCARS chrome all share the same palette, including alert-mode hue rotations.</p><p>The profiles are appended to the end of your existing HA-LCARS <code>themes.yaml</code>.</p><p>→ <a href="./ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a></p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../getting-started/installation.html">Installation</a>: how the panel is registered via the integration</li><li><a href="./persistent-helpers.html">Persistent Helpers</a>: full helper reference and manual YAML setup</li><li><a href="./alert-mode-lab.html">Alert Mode Lab</a>: colour palette customisation</li><li><a href="./../core/alert-mode.html">Alert Mode</a>: how alert mode works and how to trigger it</li><li><a href="./connectivity.html">Connectivity</a>: connection overlay reference</li><li><a href="./sounds.html">Sounds</a>: sound system reference</li><li><a href="./users-devices.html">Users &amp; Devices</a>: scoped settings management</li><li><a href="./ha-lcars-theme-profiles.html">HA-LCARS Theme Profiles</a>: LCARdS palette ↔ HA-LCARS theme integration</li></ul>',60)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
